commands:
$store = 'HKLM:\SOFTWARE\MagicXToolbox\PowerPlan'
$guidRx = '[0-9a-fA-F]{8}(-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}'
$prior = [regex]::Match((powercfg /getactivescheme | Out-String), $guidRx).Value
if (-not $prior) { Write-Error 'Could not read the currently active power scheme'; exit 1 }
$known = (Get-ItemProperty -Path $store -Name AppliedScheme -ErrorAction SilentlyContinue).AppliedScheme
# New-Item -Force on an existing key deletes its values.
if (-not (Test-Path $store)) { New-Item -Path $store -Force | Out-Null }
if ($known -and (powercfg /list | Out-String) -match [regex]::Escape($known)) {
  $guid = $known
} else {
  $out = powercfg /duplicatescheme e9a42b02-d5df-448d-aa00-03f14749eb61 2>&1
  if ($LASTEXITCODE -ne 0) { Write-Error ($out | Out-String); exit 1 }
  $guid = [regex]::Match(($out | Out-String), $guidRx).Value
  if (-not $guid) { Write-Error 'Could not read the guid of the new scheme'; exit 1 }
  Set-ItemProperty -Path $store -Name AppliedScheme -Value $guid -Force
}
if ($prior -ne $guid) { Set-ItemProperty -Path $store -Name PriorScheme -Value $prior -Force }
powercfg /setactive $guid
if ($LASTEXITCODE -ne 0) { Write-Error 'powercfg /setactive failed'; exit 1 }
exit 0
